import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods

    /**
     * Parses an Atom document from the supplied {@link InputStream} while
     * protecting against XML External Entity (XXE) attacks.
     *
     * <p>The original implementation used a shared {@link Parser} instance
     * and modified its default options inside a synchronized block. This
     * approach was error‑prone because the options could be overridden by
     * concurrent threads before the actual parse operation. The revised
     * implementation creates a fresh {@link ParserOptions} object for each
     * invocation, sets {@code resolveEntities} to {@code false}, and passes
     * those options directly to {@link Parser#parse(InputStream, ParserOptions)}.
     * This guarantees that entity resolution is disabled for every parse
     * operation regardless of threading concerns.</p>
     *
     * @param clazz   the expected element type
     * @param t       the generic type
     * @param a       annotations
     * @param mt      media type
     * @param headers HTTP headers
     * @param is      input stream containing the Atom XML
     * @return the root element of the parsed document
     * @throws IOException if parsing fails
     */
    @Override
    public T readFrom(Class<T> clazz, Type t, Annotation[] a, MediaType mt,
                      MultivaluedMap<String, String> headers, InputStream is) throws IOException {
        Parser parser = ATOM_ENGINE.getParser();

        // Create a new ParserOptions instance for this request
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        options.setResolveEntities(false); // Disable external entity resolution

        Document<T> doc;
        try {
            // Pass the options explicitly to avoid race conditions
            doc = parser.parse(is, options);
        } catch (Exception e) {
            // Wrap any parsing exception into an IOException to satisfy the method signature
            throw new IOException("Failed to parse Atom feed", e);
        }

        return doc.getRoot();
    }

    // other methods
}
