static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new NullPointerException("Directory cannot be null");
    }
    if (name == null) {
        throw new NullPointerException("Name cannot be null");
    }
    // Strip query parameters
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Resolve and normalize path
    Path targetPath = dir.toPath().toAbsolutePath().normalize()
            .resolve(name).normalize();

    // Ensure the target is within the intended directory
    if (!targetPath.startsWith(dir.toPath().toAbsolutePath().normalize())) {
        throw new IllegalArgumentException(
                "Attempt to create file outside of the target directory: " + name);
    }

    File file = targetPath.toFile();

    // Handle duplicate names
    String dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }

    // Create parent directories if needed
    File parent = file.getParentFile();
    if (parent != null && !parent.exists()) {
        parent.mkdirs();
    }

    return file;
}
