import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // ... other methods ...

    /**
     * Validates a media type token (major or subtype). A token must consist of one or more
     * characters from the set defined by RFC 7230 § 3.2.6 (tchar), or be a single '*'
     * wildcard. This method rejects null, empty strings, control characters, and any
     * characters outside the allowed set, thereby preventing header injection via
     * CR/LF or other unsafe characters.
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^(\\*|[A-Za-z0-9!#$%&'*+\\-.^_`|~]+)$");

    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Reject any control characters explicitly (e.g., CR, LF, TAB)
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isISOControl(ch)) {
                return false;
            }
        }
        return TOKEN_PATTERN.matcher(str).matches();
    }

    // ... other methods ...
}
