     * Normalizes a URI path by ensuring it has at most one leading slash
     * and that a leading slash is present when required. This prevents
     * malformed paths from being interpreted incorrectly during URI
     * construction.
     *
     * @param path the original path string
     * @return a normalized path, or {@code null} if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

