import javax.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.List;

/**
 * DefaultURLConstructor is responsible for determining the forward page
 * for a given request. The original implementation simply returned the
 * raw path info from the request, which exposed the application to
 * path‑traversal attacks. The updated implementation validates and
 * sanitises the path before returning it.
 */
public class DefaultURLConstructor implements URLConstructor
{
    // other methods

    /**
     * Returns the name of the JSP page to forward to.
     *
     * <p>The method now performs strict validation and sanitisation of
     * {@link HttpServletRequest#getPathInfo()} to prevent path traversal
     * and other injection attacks. Only filenames that match the
     * pattern {@code [A-Za-z0-9_-]+\\.jsp} are accepted. Any attempt to
     * include directory separators, relative path components, or
     * disallowed characters results in a fallback to the default page
     * ("Wiki.jsp").</p>
     *
     * @param request the HTTP request that was used to reach this page
     * @return the validated JSP page name, e.g. "Wiki.jsp" or "PageInfo.jsp"
     */
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        // Default to the main wiki page if no path was supplied
        if (pathInfo == null || pathInfo.trim().isEmpty()) {
            return "Wiki.jsp";
        }

        // Remove leading slash(es) to simplify processing
        String trimmed = pathInfo.startsWith("/") ? pathInfo.substring(1) : pathInfo;

        // Reject any path containing suspicious characters or patterns
        if (trimmed.contains("..") || trimmed.contains("\\") || trimmed.contains("%")) {
            return "Wiki.jsp";
        }

        // Split into segments and rebuild a clean path without empty or ".." parts
        String[] segments = trimmed.split("/");
        List<String> cleanSegments = new ArrayList<>();
        for (String seg : segments) {
            if (seg.isEmpty() || seg.equals("..")) {
                continue; // skip invalid segments
            }
            cleanSegments.add(seg);
        }

        // Reconstruct the path and enforce a single filename ending with .jsp
        String cleanedPath = String.join("/", cleanSegments);
        if (!cleanedPath.matches("^[A-Za-z0-9_-]+\\.jsp$")) {
            // If the resulting path is not a simple JSP filename, fall back
            return "Wiki.jsp";
        }

        return cleanedPath;
    }

    // other methods 
}
