class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from the given {@link InputStream} into the supplied
     * output buffer using a simple run‑length encoding scheme.
     *
     * <p>This implementation performs rigorous validation of the input stream
     * to guard against malformed data that could otherwise cause an infinite
     * loop or buffer overrun.  It checks for end‑of‑stream conditions,
     * validates repeat counts, and ensures that the output buffer is not
     * exceeded.</p>
     *
     * @param in  the source stream containing compressed data
     * @param out the destination buffer to receive decompressed bytes
     * @throws IOException if the stream ends prematurely or contains
     *                     invalid data
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new IOException("Unexpected end of stream while reading header byte");
            }

            if (n > 128) { // Run‑length encoded block
                int value = in.read();
                if (value == -1) {
                    throw new IOException("Unexpected end of stream while reading repeat value");
                }

                int repeatCount = n & 0x7F; // lower 7 bits give the repeat count
                if (repeatCount == 0) {
                    throw new IOException("Invalid repeat count of 0");
                }
                if (position + repeatCount > total) {
                    throw new IOException("Output buffer overflow detected");
                }

                for (int i = 0; i < repeatCount; i++) {
                    out[position++] = (byte) value;
                }
            } else { // Literal block
                int literalCount = n;
                if (literalCount == 0) {
                    throw new IOException("Invalid literal count of 0");
                }
                if (position + literalCount > total) {
                    throw new IOException("Output buffer overflow detected");
                }

                for (int i = 0; i < literalCount; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new IOException("Unexpected end of stream while reading literal data");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

