import javax.naming.ldap.StartTlsResponse;
import org.neo4j.server.security.enterprise.log.SecurityLog;

public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider {

    private final SecurityLog securityLog;

    // other methods

    /**
     * Creates an {@link LdapContext} that uses STARTTLS and performs a secure bind.
     *
     * <p>This method now validates the supplied credentials, performs the STARTTLS negotiation
     * before binding, and explicitly re‑binds after the TLS layer has been established.  This
     * prevents the previous “bind‑after‑STARTTLS” bug where credentials were added to the
     * environment but never actually used for authentication.</p>
     *
     * @param ldapContextFactory factory providing LDAP configuration
     * @param principal          user DN or bind name
     * @param credentials        user password
     * @return a fully authenticated {@link LdapContext}
     * @throws NamingException if the context cannot be created or authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                    Object principal,
                                                    Object credentials) throws NamingException {
        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("Principal and credentials must not be null");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        // Create an unauthenticated context first
        LdapContext ctx = null;
        try {
            ctx = new InitialLdapContext(env, null);

            // Negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate();

            // Re‑bind with credentials over the secured channel
            ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                    jndiLdapContextFactory.getAuthenticationMechanism());
            ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
            ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

            // Explicitly reconnect to force the bind
            ctx.reconnect(null);

            return ctx;
        } catch (AuthenticationException ae) {
            // Authentication failed – log and rethrow as a more specific exception
            securityLog.warn(withRealm("LDAP authentication failed for '%s' on '%s': %s",
                    principal, server(jndiLdapContextFactory), ae.getMessage()));
            throw ae;
        } catch (IOException | NamingException e) {
            // Any IO or naming error during TLS negotiation or bind
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to establish secure LDAP connection with '%s': %s",
                    server(jndiLdapContextFactory), e.getMessage()), e);
            if (e instanceof CommunicationException) {
                throw (CommunicationException) e;
            }
            throw new NamingException(e.getMessage());
        } finally {
            // Ensure the context is closed if an exception was thrown before returning
            if (ctx != null && !(ctx instanceof InitialLdapContext)) {
                // ctx will be returned if successful; otherwise close it
                if (!ctx.isClosed()) {
                    LdapUtils.closeContext(ctx);
                }
            }
        }
    }

    // other methods
}
