import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely extracts archive entries into {@code targetDirectory}.  The method
     * performs rigorous path validation to prevent path‑traversal attacks.
     *
     * @param supplier   provides the next readable archive entry
     * @param writer     writes the entry data to an output stream
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if extraction fails or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory once to its real (canonical) path.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Normalise separators to forward slash for consistency.
            entryName = entryName.replace('\\', '/');

            // Reject absolute paths or paths that start with a separator.
            if (entryName.startsWith("/") || entryName.startsWith("\\")) {
                throw new IOException("Entry name is absolute: " + entryName);
            }

            // Reject empty or "." entries which could cause confusion.
            if (entryName.isEmpty() || entryName.equals(".")) {
                throw new IOException("Entry name is invalid: " + entryName);
            }

            // Resolve the entry against the target directory and normalise.
            Path resolvedPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "Entry would escape target directory: " + entryName);
            }

            // Convert to File for legacy API compatibility.
            File f = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("Failed to create directory " + f);
                }
            } else {
                Path parentPath = resolvedPath.getParent();
                if (parentPath != null) {
                    Files.createDirectories(parentPath);
                }
                try (OutputStream out = Files.newOutputStream(resolvedPath)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
