        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())
                && scimUserFromRequest.isVerified()) {
            // Prevent auto‑verification of a new email address
            return false;
        }

        return true;
    }

